{
  "name": "A2D 四通道隔离式 ADC 电压采集模块",
  "name_en": "A2D 4-Channel Isolated ADC Voltage Measurement Module",
  "manufacturer": "A2D",
  "description": "这是一款带四路隔离输入的模数转换电压采集模块，可通过 RS485 通讯读取多通道电压，并支持校准参数管理与状态指示灯控制。适用于实验室中的多路电压监测、传感器信号采集和电隔离测量场景。",
  "description_en": "This is a four-channel isolated ADC-based voltage acquisition module that reads multiple voltage inputs over RS485 and supports calibration management and LED status indication. It is suitable for laboratory use in multi-channel voltage monitoring, sensor signal acquisition, and electrically isolated measurements.",
  "tag_hints": [
    "isolated ADC",
    "multi-channel voltage measurement",
    "RS485 instrumentation",
    "voltage acquisition",
    "sensor readout",
    "calibration management",
    "electrical isolation"
  ],
  "actions": [
    {
      "action_name": "auto-calibrate_voltage",
      "description": "使用两个参考电压点对指定通道进行电压校准。",
      "description_en": "Calibrate the voltage measurement of the selected channel using two reference voltage points."
    },
    {
      "action_name": "auto-measure_voltage",
      "description": "测量四个输入通道的电压。",
      "description_en": "Measure the voltages on all four input channels."
    },
    {
      "action_name": "auto-measure_voltage_at_adc",
      "description": "测量四个通道在 ADC 端的电压值。",
      "description_en": "Measure the voltages at the ADC side for all four channels."
    },
    {
      "action_name": "auto-reset",
      "description": "复位设备。",
      "description_en": "Reset the device."
    },
    {
      "action_name": "auto-reset_calibration",
      "description": "重置指定通道的校准参数。",
      "description_en": "Reset the calibration parameters for the selected channel."
    },
    {
      "action_name": "auto-save_calibration",
      "description": "保存指定通道的校准参数。",
      "description_en": "Save the calibration parameters for the selected channel."
    },
    {
      "action_name": "auto-set_led",
      "description": "设置设备指示灯状态。",
      "description_en": "Set the device LED state."
    },
    {
      "action_name": "auto-get_calibration",
      "description": "获取校准参数。",
      "description_en": "Get calibration parameters."
    },
    {
      "action_name": "auto-get_rs485_addr",
      "description": "获取 RS485 地址。",
      "description_en": "Get the RS485 address."
    },
    {
      "action_name": "auto-get_num_channels",
      "description": "获取通道数量。",
      "description_en": "Get the number of channels."
    }
  ]
}

